import org.onegram.streak.StreakEngine;import org.telegram.tgnet.ConnectionsManager;public class EngineTest {public static void main(String[] args)throws Exception {run(false,false,150);run(true,false,2);run(false,true,0);System.out.println("PASS real StreakEngine: 150 days, 130k-message day skipped, missing day and one-sided day");}static void run(boolean gap,boolean one,int expected)throws Exception {ConnectionsManager.gap=gap;ConnectionsManager.oneSided=one;ConnectionsManager.calls=0;ConnectionsManager.returned=0;StreakEngine engine=new StreakEngine(new android.content.Context());android.view.View view=new android.view.View();engine.focus(0,2);engine.get(0,2,view);long end=System.currentTimeMillis()+20000;int value=-1;while(System.currentTimeMillis()<end){value=engine.get(0,2,view);if(value>=0)break;Thread.sleep(5);}if(value!=expected)throw new AssertionError("count="+value+" expected="+expected);if(!gap&&!one&&ConnectionsManager.calls>152)throw new AssertionError("Did not skip dense day");if(engine.activeToday(0,2)==one)throw new AssertionError("activeToday");System.out.println("count="+value+", requests="+ConnectionsManager.calls+", received="+ConnectionsManager.returned);engine.close();}}